  it('replaces an incomplete trailing sequence at clean EOF on both streams', async () => {
    for (const limits of [{}, { maxStdoutBytes: 3, maxStderrBytes: 3 }]) {
      const result = await new ProcessScripts().run(
        request({
          args: [
