5	export interface ProcessScriptsOptions {
6	  /** Cap on captured stdout and stderr, each. Default 10 MiB. */
7	  maxOutputBytes?: number;
8	  /** Environment the script inherits before the request's own variables are applied. Default: this process's environment. */
9	  baseEnv?: NodeJS.ProcessEnv;
10	  /** Injected for tests. */
11	  spawnImpl?: typeof spawn;
12	  platform?: NodeJS.Platform;
13	}
