15	/** `taskkill` exit code when no process with the PID exists. */
16	const TASKKILL_NOT_FOUND = 128;
17	
18	const hasExited = (child: ChildProcess): boolean =>
19	  child.exitCode !== null || child.signalCode !== null;
20	
21	/**
22	 * Kill a process and everything it started. Windows has no process groups or POSIX signals, so
23	 * `taskkill /T /F` is used there; elsewhere the child was started detached as a group leader and
24	 * the whole group is signalled.
25	 *
26	 * On Windows a root that is verifiably gone counts as released: Node has observed its exit, or
27	 * taskkill found no process with its PID and Node then reports the exit. A root Node saw exit is
28	 * never signalled, because Node has closed its handle and Windows may already have reused the PID.
29	 * Any other taskkill failure leaves the state undetermined and reports `false`. A descendant that
30	 * inherited the root's output keeps it open; callers confirm release only when it closes.
31	 */
32	export function killTree(
33	  child: ChildProcess,
34	  platform: NodeJS.Platform = process.platform,
35	  spawnImpl: typeof spawn = spawn,
36	): Promise<boolean> {
37	  if (child.pid === undefined) return Promise.resolve(true);
38	  if (platform === 'win32') {
39	    if (hasExited(child)) return Promise.resolve(true);
40	    return new Promise((resolve) => {
41	      let killer: ChildProcess;
42	      try {
43	        killer = spawnImpl('taskkill', ['/pid', String(child.pid), '/T', '/F'], {
44	          stdio: 'ignore',
45	          windowsHide: true,
46	        });
47	      } catch {
48	        try {
49	          child.kill();
50	        } catch {
51	          /* no confirmed root cleanup */
52	        }
53	        resolve(false);
54	        return;
55	      }
56	      // Killing just the root is best effort; it never establishes tree cleanup.
57	      killer.once('error', () => {
58	        try {
59	          child.kill();
60	        } catch {
61	          /* no confirmed root cleanup */
62	        }
63	        resolve(false);
64	      });
65	      killer.once('close', (code) => {
66	        if (code !== TASKKILL_NOT_FOUND) resolve(code === 0);
67	        // No process has the PID, so the root is no longer running: it exited on its own before
68	        // taskkill looked. Release is claimed once Node reports that exit; the caller's deadline
69	        // bounds this wait.
70	        else if (hasExited(child)) resolve(true);
71	        else child.once('exit', () => resolve(true));
72	      });
73	    });
74	  }
75	  try {
76	    process.kill(-child.pid, 'SIGKILL');
77	    return Promise.resolve(true);
78	  } catch {
79	    try {
80	      child.kill('SIGKILL');
81	    } catch {
82	      /* no confirmed root cleanup */
83	    }
84	    return Promise.resolve(false);
85	  }
86	}
